TARGET=dict(manufacturer='Yamaha',model='YZ450F',model_year=2026,region='US',variant='standard')
def printed(p):
    if p==7:return 'Symbols (unnumbered)'
    if 49<=p<=84:return '2-'+str(p-47)
    if 85<=p<=122:return '3-'+str(p-84)
    if 204<=p<=292:return '5-'+str(p-203)
    if 294<=p<=303:return '6-'+str(p-293)
    raise ValueError('Unreviewed printed-page mapping '+str(p))
def save(name,obj):
    p=ROOT/name
    data=(json.dumps(obj,ensure_ascii=True,indent=2)+'\n').encode()
    if p.exists():
        if json.loads(p.read_bytes())==obj: return
        raise RuntimeError('Frozen artifact differs: '+name)
    p.write_bytes(data)
def step(i,title,text,pages,verify,record=True,diagram=False):
    return dict(id=i,title=title,instruction=text,source_pdf_pages=pages,verification=verify if isinstance(verify,list) else [verify],record_required=record,diagram_reference_required=diagram,source_links=[URL+'#page='+str(p) for p in pages],origin='Original source-based summary; observation fields are application workflow')
def procedure(slug,title,steps,entry,exit,tools,parts,exclusions,components):
    policy=json.loads((ROOT/'record-policy.json').read_text()) if (ROOT/'record-policy.json').exists() else {}
    for n,s in enumerate(steps):
        if slug in policy:s['record_required']=s['id'] in policy[slug]
        s['depends_on']=[] if n==0 else [steps[n-1]['id']]
    pages=sorted({7,56}|{p for s in steps for p in s['source_pdf_pages']})
    obj=dict(schema_version=1,id='yamaha-2026-yz450f-'+slug,target=TARGET,scope_confirmed=True,title=title,status='SOURCE_REVIEWED_BOUNDED_PROCEDURE',completeness='Complete bounded bench operation from the declared entry state to the declared exit state. Whole-bike access and downstream engine closure are separate dependencies.',source=dict(source_url=URL,document_sha256=HASH,document_revision='D03-2819U-10 / LIT-11626-39-20; First edition April 2025',pdf_pages=pages,printed_pages=[printed(p) for p in pages],review_status='APPROVED',review_note='All cited operation pages visually reviewed. General symbols and conditional torque rules retained.'),applicability=dict(included='Exact US2026 YZ450F standard stock components only',excluded=exclusions,year_inheritance='NONE'),affected_components=components,required_tools=[dict(name=x) for x in tools],required_parts=[dict(name=x) for x in parts],preflight=entry,entry_state=entry,exit_state=exit,critical_stop_conditions=['Any required measurement unresolved or replacement criteria not satisfied.','Unidentified diagram orientation, missing parts, damage or abnormal binding.'],material_policy=dict(LT='Locking agent (LOCTITE) per PDF7. Grade unspecified by this manual; no grade inferred.',lubrication='Follow each explicit E/M/LS/S application; general dry torque does not override a lubricated joint.'),steps=steps,reviewed_at='2026-09-13',runtime_integration_requirement='Enforce entry state and record_required. Completion certifies this bounded operation only; no automatic completion of upstream/downstream work.')
    save(slug+'.procedure.json',obj)
    return obj

# Both assemblies are physically removed into labeled trays and rebuilt in their OEM stack order.
trans=[
step('entry','Confirm the exposed transmission','Start with the engine on the bench, right crankcase separated and both shaft assemblies exposed in the left case. Preserve the installed collar until the two shafts can be removed together. Record existing fork positions and direction.',[286,287,288,289],'Case-open entry state confirmed; positions recorded.',True,True),
step('remove','Lift out the gear train','Withdraw the long and short fork guide bars and retain all four end springs. Lift out the drum and forks, labeled3(R),2(C),1(L). Remove main and drive axles together; lightly tap the drive axle with a soft hammer if needed. Keep the collar in place during removal, then retain it separately.',[287,288,289],'Two shafts, three identified forks, drum, two bars, four springs and collar accounted for.',True,True),
step('strip','Lay out both shaft stacks','Remove each shaft gear, collar, washer and circlip into an ordered tray using the two exploded stacks. Preserve every washer face and circlip location. Removed circlips are replaced at assembly; do not substitute a remembered generic gearbox order.',[286,290,291],'Both original stack orders recorded; new circlips obtained.',True,True),
step('fork-check','Inspect forks, bars and drum','Check fork followers and pawls for bends, scoring, damage or wear; replace defective forks. Roll each guide bar on a flat surface and replace a bent bar without straightening it. Check fork sliding movement; rough movement requires forks and guide bars as a set. Replace a drum assembly with worn/damaged grooves or segment.',[289],'Fork, bar and drum results and any replacement decisions recorded.'),
step('shaft-check','Measure both shaft runouts','Support the main axle in a centering device and measure with a dial indicator at the illustrated point. Check the drive axle on the illustrated supports in the same way. Limit is0.08mm for either shaft. Replace an out-of-limit axle.',[289,290],['Main axle runout in mm saved.','Drive axle runout in mm saved.'],True,True),
step('gear-check','Assess each gear and dog','Inspect every gear for blue heat discoloration, pitting and wear, and each dog for cracks, damage or rounded edges. Replace defective gears. Check sliding movement and replace gears that remain rough. Record the inspected part and decision before rebuilding.',[290],'Gear-by-gear assessment and replacement list saved.'),
step('main-stack','Build the main axle','Fit fourth pinion22T, third pinion20T, collar, fifth pinion21T and second pinion16T in the illustrated order, including every intervening washer/circlip. Apply molybdenum-disulfide oil to idler-gear inner/end faces and sliding-gear inner faces. Use the exploded stack for all shoulder orientations.',[286,290],'Main axle stack, tooth counts, washers and lubrication verified.',True,True),
step('drive-stack','Build the drive axle','Fit collar, second wheel26T, fifth wheel21T, third wheel27T, fourth wheel25T, collar, first wheel28T and a new O-ring in the illustrated stack with its washers/circlips. Apply molybdenum-disulfide oil to idler gear/collar inner and end faces and sliding-gear inner faces. Lubricate the new O-ring with lithium-soap grease.',[286,290],'Drive axle stack, tooth counts, washers, new O-ring and lubrication verified.',True,True),
step('clips','Verify each new circlip','Install the washers and new circlips at their exact diagram positions. The sharp-edged corner faces away from the adjacent washer/gear. Position both open ends evenly on spline crests and confirm full groove seating; inspect each location separately.',[290,291],'Every circlip new, seated and correctly oriented.',True,True),
step('shafts-install','Return both shafts together','Grease the case oil-seal lip with lithium-soap grease and fit the collar without rolling the lip. Oil both shaft bearings. Install the main and drive axles simultaneously into the left crankcase.',[291],'Collar lip undamaged; both shafts seated together.',True,True),
step('forks-install','Engage the three forks and drum','Oil fork grooves, drum grooves and drum bearing contact surfaces. Fork1(L) engages fifth wheel gear on the drive axle; fork3(R) engages fourth wheel gear on that axle. Fork2(C) engages third pinion on the main axle. Engage the drum as illustrated.',[291,292],'L/C/R forks matched to correct gears and drum tracks.',True,True),
step('bars-install','Install the bars and four springs','Lightly screw each spring into its guide-bar end beforehand. Oil the bars; install the long and short bars in the illustrated locations with all four springs retained.',[287,292],'Two correct bars and all four springs installed.',True,True),
step('function','Check transmission movement before case closure','Turn the shafts by hand while operating the drum through the gear selections. Confirm smooth drum, fork and transmission movement. Correct any binding before case closure; do not mark the engine assembled at this bench checkpoint.',[292],'Selection and rotation observations saved; smooth operation confirmed.',True,True)]
procedure('transmission-bench-v1','Rebuild the stock transmission on the bench',trans,['Engine removed; right crankcase already separated under the case-opening operation.','Stock shafts/gears/forks identified; original positions retained.'],['Transmission installed in left case and function checked; right case remains open.'],['Centering device, shaft supports and dial indicator accurate for0.08mm','Flat inspection surface, soft hammer, circlip pliers, labeled trays'],['New shaft circlips and drive-axle O-ring','Engine oil, molybdenum-disulfide oil, lithium-soap grease','Exact stock replacement gears/forks/bars/drum/shafts as inspection requires'],['Case separation and closure','Engine removal/refit','Aftermarket ratios or components'],['engine','transmission'])

pump=[
step('entry','Confirm pump access','Start with the right crankcase cover, clutch idle gear and oil-pump drive gear already removed. Preserve the relief-valve parts behind the pump in their installed condition; this operation does not remove that valve.',[269,274],'Pump access confirmed; relief-valve assembly left installed.',True,True),
step('remove','Remove and open the pump','Remove the two mounting bolts and lift the pump away. Remove the outer circlip, outer rotor1, inner rotor1, its dowel and washer. Remove the pump-cover bolt and cover, then outer rotor2, inner rotor2, dowel and drive shaft. Keep the two rotor sets and pins identified.',[274,275],'Two rotor sets, washer, circlip, two pins, shaft, housing and cover accounted for.',True,True),
step('inspect','Inspect the pump assembly','Inspect the cover, drive shaft and housing for cracks, damage or wear. Replace the complete pump assembly if defective. Check turning movement; repeat inspection or replace the assembly if it is rough. No numerical rotor clearance is invented here.',[275],'Condition and replacement/retain decision recorded.'),
step('inner','Assemble the inner rotor set','Oil the shaft, inner rotor2 and outer rotor2. Fit the shaft, dowel and rotors into the housing, seating the dowel in the inner rotor2 slit. Follow the diagram for the rotor set sides.',[274,275],'Inner rotor2 dowel engaged; surfaces oiled.',True,True),
step('cover','Secure the cover','Install the pump cover and tighten its bolt to6Nm with LOCTITE locking agent. The manual does not name a grade.',[275],'Cover seated;6Nm and locking-agent application recorded.',True,True),
step('outer','Assemble the outer rotor set','Fit the washer, dowel, inner rotor1, outer rotor1 and circlip. Oil both rotors and engage the dowel in the inner rotor1 groove. Confirm the circlip is fully seated.',[274,275],'Outer rotor1 dowel engaged; washer and clip present.',True,True),
step('mount','Refit and verify the pump','Mount the pump with its two bolts at5Nm using LOCTITE locking agent. Turn the pump by hand after tightening; it must move smoothly. Correct binding or replace the assembly before proceeding to the drive-gear installation.',[275],'5Nm mounting and smooth post-tightening rotation saved.',True,True)]
procedure('oil-pump-bench-v1','Inspect and rebuild the stock oil pump',pump,['Right cover, clutch idle gear and oil-pump drive gear removed.','Relief-valve spring/ball/seat left installed in case.'],['Pump assembled, mounted and rotating smoothly; drive gear and covers remain to be installed.'],['Calibrated low-range torque wrench accurate at5 and6Nm','Circlip tools and clean labeled trays'],['Engine oil','LOCTITE locking agent; OEM grade unspecified','Exact complete replacement pump if required'],['Relief-valve disassembly','Engine access and cover closure','Unspecified rotor-clearance limits'],['engine','oil_pump'])

primary=[
step('entry','Confirm exposed primary drive','Start with the clutch idle gear and right crankcase cover removed. Record the balancer timing marks and stock gear arrangement. Keep the crankshaft supported in the assembled case.',[269,270],'Entry state and timing marks recorded.',True,True),
step('unlock','Release both gear nuts','Straighten the balancer lock-washer tab. Insert an aluminum plate between the illustrated balancer drive and driven gear teeth to hold them while loosening the balancer-driven and primary-drive nuts. Do not replace the plate with a hardened tool.',[271],'Nuts released without tooth damage.',True,True),
step('remove','Remove the primary and balancer stacks','Remove nuts and washer, primary gear, collar, starter reduction gear, circlip, starter clutch and balancer drive gear in the illustrated order. Remove the balancer lock washer, driven gear and oil-pump drive gear. Keep every part identified. Leave the separate damper assembly intact unless separately serviced.',[269,270],'Both stacks retained; damper intact.',True,True),
step('inspect','Inspect gears and starter clutch','Replace worn/damaged primary, reduction, balancer and oil-pump gears. Primary drive/driven gears are replaced as a set when either is damaged/worn, noisy or has free play. Replace the starter-clutch assembly for burrs, chips, roughness or wear.',[256,271],'Gear and starter-clutch results saved.'),
step('oneway','Check starter-clutch direction','Fit the starter clutch to the balancer drive gear and then the reduction gear. Viewed exactly as the diagram, turning the balancer drive gear counterclockwise must freewheel; clockwise must engage. Replace the starter clutch if either test fails.',[271],'Both directional test results recorded.',True,True),
step('driven','Set the balancer driven gear','Install oil-pump drive gear and balancer driven gear, aligning the illustrated lower spline on the gear with that on the shaft.',[271,272],'Lower splines aligned.',True,True),
step('drive','Set balancer timing','Install balancer drive gear with its lower spline aligned to the crankshaft lower spline. Align the punched drive/driven gear timing marks with one another.',[272],'Both spline and timing-mark alignments recorded.',True,True),
step('clean','Prepare primary nut surfaces','Thoroughly remove oil from crankshaft threads, washer contact faces and the primary-drive nut threads/contact face before the specified molybdenum-grease application. Do not carry over the2025 primary-nut preparation or torque.',[272],'Specified surfaces cleaned and oil removed.'),
step('starter-install','Install the starter clutch and stack','Fit a new balancer lock washer and the balancer nut. Oil the starter clutch and fit its manufacturer mark outward. Verify the illustrated clearance between clutch and balancer drive gear is at least0.7mm. Fit circlip, oiled reduction gear, collar, primary gear and washer in order.',[269,272],'New lock washer, outward mark, seated clip and measured clearance saved.',True,True),
step('torque','Tighten both nuts with the specified preparation','Apply molybdenum-disulfide grease to crankshaft threads, washer contact surfaces and primary-drive nut threads/contact face. Hold the illustrated balancer teeth with an aluminum plate. Tighten balancer-driven nut50Nm and primary-drive nut170Nm. These are exact2026 settings.',[272,273],'50Nm/170Nm results and molybdenum-grease application recorded.',True,True),
step('lock','Lock and check the completed gear stack','Bend the new balancer lock-washer tab against the nut as shown. Remove the holding plate and account for it. Verify the balancer marks, starter-clutch installation and retained clips before the clutch/cover work resumes.',[272,273],'Lock tab, timing marks, clip and tool removal verified.',True,True)]
procedure('primary-balancer-bench-v1','Service the primary drive and starter clutch',primary,['Right crankcase cover and clutch idle gear removed.','Crankshaft and balancer installed in closed crankcases.'],['Primary/balancer/starter-clutch stacks installed and checked; clutch/cover closure still required.'],['Calibrated torque wrench covering50 and170Nm','Aluminum plate for illustrated gear holding','Clearance measuring tool, circlip tools'],['New balancer lock washer','Engine oil and molybdenum-disulfide grease','Exact stock replacement gears/starter clutch as required'],['Clutch boss nut operation','Crankcase opening','Starter electric motor internals'],['engine','primary_drive','starter_clutch'])

def manifest():
    artifacts=[]
    for p in sorted(ROOT.glob('*.procedure.json')):
        d=json.loads(p.read_text()); artifacts.append(dict(path=p.name,kind='procedure',sha256=hashlib.sha256(p.read_bytes()).hexdigest(),source_id='yamaha26',target=d['target']))
    data=dict(schema_version=1,id='engine-pass3-reviewed-procedures',reviewed_at='2026-09-13',database_writes=False,sources=[dict(id='yamaha26',url=URL,local_pdf_path='C:/Users/kylej/AppData/Local/Temp/D03-2819U-10_02.pdf',sha256=HASH)],artifacts=artifacts)
    (ROOT/'source-review-manifest.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
manifest()
